const fs = require('fs');
const path = require('path');

/**
 * PII-safe sanitisation for EOFY audit exports before Claude analysis.
 */

const crypto = require('crypto');

const PERSONAL_FIELD_PATTERNS = [
  /partner/i,
  /email/i,
  /phone/i,
  /login/i,
  /author/i,
  /commercial_partner/i,
  /acc_number/i,
  /payment_ref/i,
];

const BANK_FIELD_PATTERNS = [/acc_number/i, /bank_/i, /payment_ref/i];

const TEXT_COMPACT_FIELDS = ['name', 'ref', 'description', 'payment_ref', 'message'];

function hashEntity(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return raw;
  const h = crypto.createHash('sha256').update(raw).digest('hex').slice(0, 12);
  if (/^ENTITY_[a-f0-9]+$/i.test(raw)) return raw;
  return `ENTITY_${h}`;
}

function compactText(value, maxLen = 64) {
  const raw = String(value ?? '').trim();
  if (!raw || raw === 'false') return raw;
  if (raw.length <= maxLen) return raw;
  const h = crypto.createHash('sha256').update(raw).digest('hex').slice(0, 12);
  return `${raw.slice(0, maxLen - 30)}... [TEXT_TRUNCATED hash=${h} len=${raw.length}]`;
}

function matchesAny(field, patterns) {
  return patterns.some((p) => p.test(field));
}

function sanitiseRecord(record, modelKey, policy, sourceFile) {
  const out = { ...record };
  let personal = 0;
  let bank = 0;
  let compacted = 0;

  for (const [field, value] of Object.entries(out)) {
    if (field === '_sanitisation' || field.endsWith('_id')) continue;

    if (policy.partner_names_hashed && matchesAny(field, PERSONAL_FIELD_PATTERNS)) {
      if (typeof value === 'string' && value && value !== 'false') {
        out[field] = hashEntity(value);
        personal += 1;
      }
    }

    if (policy.bank_details_redacted && matchesAny(field, BANK_FIELD_PATTERNS)) {
      if (typeof value === 'string' && value && value !== 'false') {
        out[field] = '[REDACTED_BANK]';
        bank += 1;
      }
    }

    if (policy.descriptions_compacted && matchesAny(field, TEXT_COMPACT_FIELDS)) {
      if (typeof value === 'string' && value.length > policy.text_compact_max_len) {
        out[field] = compactText(value, policy.text_compact_max_len);
        compacted += 1;
      }
    }

    if (field.endsWith('_label') && policy.partner_names_hashed) {
      if (typeof value === 'string' && value && value !== 'false') {
        out[field] = hashEntity(value);
        personal += 1;
      }
    }
  }

  out._sanitisation = {
    model: modelKey,
    source_file: sourceFile,
    sanitised_at_utc: new Date().toISOString(),
    personal_fields_redacted: personal,
    bank_fields_redacted: bank,
    compacted_text_fields: compacted,
    policy: 'partner/user identities hashed; bank details redacted; descriptions compacted',
  };

  return out;
}

module.exports = {
  sanitiseRecord,
  hashEntity,
  compactText,
};

/**
 * Profile sanitised JSONL exports for Claude readiness summary.
 */

const fs = require('fs');
const path = require('path');

function profileJsonlFile(filePath, modelKey) {
  const summary = {
    model: modelKey,
    files: 1,
    rows: 0,
    distinct_ids: 0,
    field_count: 0,
    fields: [],
    min_date: null,
    max_date: null,
    debit_total: 0,
    credit_total: 0,
    balance_total: 0,
    amount_total: 0,
    pii_hits_after: 0,
    personal_fields_redacted: 0,
    bank_fields_redacted: 0,
    compacted_text_fields: 0,
  };

  const ids = new Set();
  const fields = new Set();
  const dateCandidates = ['date', 'date_order', 'invoice_date', 'payment_date', 'create_date', 'start_at'];

  if (!fs.existsSync(filePath)) return summary;

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n').filter((l) => l.trim());
  for (const line of lines) {
    try {
      const row = JSON.parse(line);
      summary.rows += 1;
      if (row.id) ids.add(row.id);
      Object.keys(row).forEach((k) => fields.add(k));
      if (row.debit) summary.debit_total += Number(row.debit) || 0;
      if (row.credit) summary.credit_total += Number(row.credit) || 0;
      if (row.balance) summary.balance_total += Number(row.balance) || 0;
      if (row.amount_total) summary.amount_total += Number(row.amount_total) || 0;
      if (row._sanitisation) {
        summary.personal_fields_redacted += row._sanitisation.personal_fields_redacted || 0;
        summary.bank_fields_redacted += row._sanitisation.bank_fields_redacted || 0;
        summary.compacted_text_fields += row._sanitisation.compacted_text_fields || 0;
      }
      for (const d of dateCandidates) {
        const v = row[d];
        if (v && v !== false && typeof v === 'string') {
          if (!summary.min_date || v < summary.min_date) summary.min_date = v;
          if (!summary.max_date || v > summary.max_date) summary.max_date = v;
        }
      }
      const piiScan = JSON.stringify(row);
      if (/@/.test(piiScan) || /\b04\d{8}\b/.test(piiScan)) summary.pii_hits_after += 1;
    } catch {
      // skip bad lines
    }
  }

  summary.distinct_ids = ids.size;
  summary.fields = [...fields].sort();
  summary.field_count = summary.fields.length;
  return summary;
}

function buildReadinessSummary(snapshotId, paths, modelSummaries, manifests) {
  const totalRows = modelSummaries.reduce((a, m) => a + m.rows, 0);
  const piiAfter = modelSummaries.reduce((a, m) => a + m.pii_hits_after, 0);
  const gaps = manifests.filter((m) => m.status !== 'written' && m.status !== 'empty');

  return {
    summary: {
      ok: gaps.length === 0,
      status: piiAfter > 0 ? 'REVIEW_PII_REMAINS' : 'READY_FOR_CLAUDE',
      selected_snapshot_id: snapshotId,
      raw_root: paths.raw_root,
      sanitised_root: paths.sanitised_root,
      report_root: paths.report_root,
      files_profiled: modelSummaries.length,
      models_profiled: modelSummaries.length,
      total_rows: totalRows,
      parse_errors: 0,
      pii_after_total: piiAfter,
      extraction_errors: gaps.length,
      combined_payload_jsonl: path.join(paths.report_root, 'claude_payload_all.jsonl'),
      generated_at_utc: new Date().toISOString(),
    },
    model_summaries: modelSummaries,
    extraction_gaps: gaps.map((g) => ({
      model: g.model || g.export_key,
      status: g.status,
      error: g.error?.data?.message || g.error?.message || g.message || 'unknown',
    })),
  };
}

module.exports = {
  profileJsonlFile,
  buildReadinessSummary,
};


const scope = {
  "business": "Ride Electric Brisbane",
  "company_id": 4,
  "company_name": "Ride Electric Brisbane",
  "financial_year_start": "2024-07-01",
  "financial_year_end": "2025-06-30",
  "timezone": "Australia/Brisbane",
  "scope_note": "Brisbane pilot only (company_id 4). Do not generalise findings to other Ride Electric entities unless the data explicitly supports it.",
  "n8n_server": "https://workflow.rideai.com.au",
  "export_paths": {
    "raw_root": "/home/node/.n8n/odoo_eofy_exports",
    "sanitised_root": "/home/node/.n8n/odoo_eofy_exports_sanitised",
    "report_root": "/home/node/.n8n/odoo_eofy_reports"
  },
  "export_defaults": {
    "batch_size": 500,
    "sample_limit_per_model": null,
    "order": "id asc",
    "sanitise": {
      "partner_names_hashed": true,
      "bank_details_redacted": true,
      "descriptions_compacted": true,
      "text_compact_max_len": 64
    }
  },
  "handover_caveats": [
    "This is Brisbane/company_id 4 only.",
    "This is not group-wide unless explicitly expanded.",
    "Missing data is an extraction gap, not proof of no issue.",
    "Sanitised identifiers are stable for grouping but not re-identification.",
    "Do not run financial conclusions without account_move_line.",
    "Do not run POS conclusions without pos_order, pos_order_line, and pos_payment."
  ]
};
const input = $input.first().json;
const snapshotId = input.snapshot_id;
if (!snapshotId) throw new Error('snapshot_id required — pass from workflow 01 output');

const rawRoot = scope.export_paths.raw_root;
const sanitisedRoot = path.join(scope.export_paths.sanitised_root, snapshotId);
const reportRoot = path.join(scope.export_paths.report_root, snapshotId);
fs.mkdirSync(sanitisedRoot, { recursive: true });
fs.mkdirSync(reportRoot, { recursive: true });

const policy = scope.export_defaults.sanitise;
const manifests = [];
const modelSummaries = [];

const rawFiles = fs.readdirSync(rawRoot).filter(f => f.startsWith(snapshotId) && f.endsWith('.jsonl'));

for (const file of rawFiles) {
  const rawPath = path.join(rawRoot, file);
  const sanitisedPath = path.join(sanitisedRoot, file.replace('.jsonl', '.sanitised.jsonl'));
  const manifestPath = path.join(rawRoot, file.replace('.jsonl', '.manifest.json'));
  let manifest = {};
  if (fs.existsSync(manifestPath)) {
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  }

  const exportKey = manifest.export_key || file.split('__')[2] || 'unknown';
  const lines = fs.readFileSync(rawPath, 'utf8').split('\n').filter(l => l.trim());
  const outLines = lines.map(line => {
    const row = JSON.parse(line);
    return JSON.stringify(sanitiseRecord(row, exportKey, policy, file));
  });
  fs.writeFileSync(sanitisedPath, outLines.join('\n') + (outLines.length ? '\n' : ''));
  modelSummaries.push(profileJsonlFile(sanitisedPath, exportKey));
  manifests.push(manifest);
}

const summary = buildReadinessSummary(snapshotId, {
  raw_root: rawRoot,
  sanitised_root: sanitisedRoot,
  report_root: reportRoot,
}, modelSummaries, manifests);

const payloadPath = path.join(reportRoot, 'claude_payload_all.jsonl');
const payloadLines = [];
for (const file of fs.readdirSync(sanitisedRoot).filter(f => f.endsWith('.sanitised.jsonl'))) {
  const content = fs.readFileSync(path.join(sanitisedRoot, file), 'utf8').split('\n').filter(l => l.trim());
  for (const line of content) {
    payloadLines.push(line);
  }
}
fs.writeFileSync(payloadPath, payloadLines.join('\n') + (payloadLines.length ? '\n' : ''));

const summaryPath = path.join(reportRoot, 'claude_readiness_summary.json');
fs.writeFileSync(summaryPath, JSON.stringify(summary, null, 2));

return [{
  json: {
    ok: true,
    snapshot_id: snapshotId,
    readiness_status: summary.summary.status,
    summary_path: summaryPath,
    payload_path: payloadPath,
    extraction_errors: summary.extraction_gaps.length,
    total_rows: summary.summary.total_rows,
  }
}];
